/// <summary>
/// MPJ_33814_CustomerAccountStatementPerf
/// This change applies to all batches where runtime batch tasks are created from the main parent task
/// </summary>
[ExtensionOf(tableStr(Batch))]
final class METBatch_Table_Extension
{
}

Method.Source:
/// <summary>
/// The customer statement main/parent task will be manually updated with max retry 0 before running with parallel processing
/// The child batch tasks created at runtime need to inherit the max retry from the parent instead of default value 5
/// max rety 5 will cause duplicate emails if one of the customer as an empty email address
/// </summary>
/// <param name = "batchInfo"><c>BatchInfo</c> class</param>
void insert(BatchInfo batchInfo)
{
    // if we have batchInfo
    if (batchInfo)
    {
        // if we have a parent task
        recId inheritFromTaskId = batchInfo.parmInheritFromTaskId();
        if (inheritFromTaskId)
        {
            // find the parent task
            Batch batch = Batch::findRecId(inheritFromTaskId);
            if (batch)
            {
                BatchJob batchJob;
                select METBatchCopyMaxRetries from batchJob where batchJob.RecId == this.BatchJobId;
                
                // if copy max retries is enabled
                if (batchJob.METBatchCopyMaxRetries)
                {
                    // Overwrite the default max retry 5 to the parent max retry (0 for customer statement with parallel processing)
                    this.RetriesOnFailure = batch.retriesOnFailure;
                }
            }
        }
    }
    
    next insert(batchInfo);
}
